const TournamentContactContext = createContext(null);
function ParticipantName({ name }) {
    const tournamentId = useContext(TournamentContactContext);
    if (!tournamentId || !name || ['BYE', 'TBD'].includes(name)) return <>{name}</>;
    const contact = async () => {
        try {
            const result = await apiFetch('/api/tournaments/' + tournamentId + '/contact/' + encodeURIComponent(name));
            Swal.fire({ titleText: '@' + result.nickname, text: 'Atur jadwal pertandingan melalui WhatsApp.', showConfirmButton: false, showCloseButton: true, didOpen: () => {
                const link = document.createElement('a'); link.href = result.whatsapp_url; link.target = '_blank'; link.rel = 'noopener noreferrer'; link.className = 'button button-lime participant-whatsapp'; link.textContent = 'Hubungi via WhatsApp'; Swal.getHtmlContainer().appendChild(link);
            } });
        } catch (error) { swalError(error); }
    };
    return <button type="button" className="participant-name" onClick={contact} aria-label={'Hubungi ' + name}>{name}</button>;
}
