function useOnlineVisitors() {
    const [online, setOnline] = useState(null);
    useEffect(() => {
        let disposed = false;
        const heartbeat = () => apiFetch('/api/public/presence', { method: 'POST' }).then((data) => {
            if (!disposed) setOnline(Number(data.online || 0));
        }).catch(() => {});
        heartbeat();
        const timer = window.setInterval(heartbeat, 60000);
        return () => { disposed = true; window.clearInterval(timer); };
    }, []);
    return online;
}
