function AuthPage({ mode, navigate, onAuthenticated }) {
    const register = mode === 'register'; const [form, setForm] = useState({ name: '', nickname: '', phone: '', password: '', password_confirmation: '', photo: null }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
    const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
    const submit = async (event) => { event.preventDefault(); setError(''); setBusy(true); try { let options; if (!register) options = { method: 'POST', body: JSON.stringify({ nickname: form.nickname, password: form.password }) }; else { const body = new FormData(); ['name', 'nickname', 'phone', 'password', 'password_confirmation'].forEach((key) => body.append(key, form[key])); if (form.photo) body.append('photo', form.photo); options = { method: 'POST', body }; } onAuthenticated(await apiFetch('/api/auth/' + (register ? 'register' : 'login'), options)); } catch (requestError) { setError(requestError.message); } finally { setBusy(false); } };
    return <div className="auth-screen"><div className="auth-stage"><button className="auth-brand" onClick={() => navigate('/')}><Brand /></button><div className="auth-visual"><div className="eyebrow eyebrow-light">Neverland member portal</div><h1>{register ? 'Enter the arena.' : 'Welcome back.'}</h1><p>{register ? 'Build your player identity and join the next bracket.' : 'Your roster, events, and next match are waiting.'}</p><div className="auth-score"><span className="live-dot" /><span className="mono">SEASON 2025 / ONLINE</span><strong>01</strong></div></div><section className="auth-form-card"><div className="auth-card-top"><div><div className="eyebrow">Account access</div><h2>{register ? 'Create member' : 'Sign in'}</h2></div><button className="icon-button" onClick={() => navigate('/')}><X size={16} /></button></div><div className="auth-mode-toggle"><button className={!register ? 'active' : ''} onClick={() => navigate('/login')}>Masuk</button><button className={register ? 'active' : ''} onClick={() => navigate('/register')}>Daftar</button></div><form className="auth-form" onSubmit={submit}>{register && <div className="field"><label>Nama lengkap</label><input required value={form.name} onChange={(event) => update('name', event.target.value)} /></div>}<div className="field"><label>Nickname / username</label><input required minLength="3" autoComplete="username" value={form.nickname} onChange={(event) => update('nickname', event.target.value)} /></div><div className="field"><label>Password</label><input required minLength="8" type="password" autoComplete={register ? 'new-password' : 'current-password'} value={form.password} onChange={(event) => update('password', event.target.value)} /></div>{register && <><div className="field"><label>Nomor HP / WhatsApp<input required type="tel" autoComplete="tel" placeholder="08xxxxxxxxxx" value={form.phone} onChange={(event) => update('phone', event.target.value)} /></label><small>Digunakan sesama peserta turnamen untuk menghubungi kamu.</small></div><div className="field"><label>Konfirmasi password</label><input required minLength="8" type="password" autoComplete="new-password" value={form.password_confirmation} onChange={(event) => update('password_confirmation', event.target.value)} /></div><div className="field"><label>Foto player <span className="muted">(opsional)</span></label><input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => update('photo', event.target.files?.[0] || null)} /></div></>}{error && <div className="form-error">{error}</div>}<button className="button button-dark full-button" disabled={busy}>{busy ? 'Memproses...' : register ? 'Create member account' : 'Enter workspace'} <ArrowUpRight size={14} /></button></form><p className="auth-hint">{register ? 'Public profile hanya memakai nickname dan foto.' : <>Demo: <span className="mono">admin</span> / <span className="mono">password</span></>}</p></section></div></div>;
}

function AuthPanel({ onClose, onAuthenticated }) {
    const [mode, setMode] = useState('login'); const [form, setForm] = useState({ name: '', nickname: '', phone: '', password: '', password_confirmation: '', photo: null }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
    const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
    const submit = async (event) => { event.preventDefault(); setError(''); setBusy(true); try { let options; if (mode === 'login') options = { method: 'POST', body: JSON.stringify({ nickname: form.nickname, password: form.password }) }; else { const body = new FormData(); ['name', 'nickname', 'phone', 'password', 'password_confirmation'].forEach((key) => body.append(key, form[key])); if (form.photo) body.append('photo', form.photo); options = { method: 'POST', body }; } onAuthenticated(await apiFetch('/api/auth/' + mode, options)); } catch (requestError) { setError(requestError.message); } finally { setBusy(false); } };
    return <div className="auth-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><section className="auth-panel" role="dialog" aria-modal="true" aria-labelledby="auth-title"><div className="auth-head"><div><div className="eyebrow">Neverland account</div><h2 id="auth-title">{mode === 'login' ? 'Welcome back.' : 'Join the roster.'}</h2><p>{mode === 'login' ? 'Masuk untuk mengakses workspace kamu.' : 'Buat akun member dengan data minimal.'}</p></div><button className="auth-close" onClick={onClose}><X size={16} /></button></div><div className="auth-tabs"><button type="button" className={'auth-tab ' + (mode === 'login' ? 'active' : '')} onClick={() => { setMode('login'); setError(''); }}>Masuk</button><button type="button" className={'auth-tab ' + (mode === 'register' ? 'active' : '')} onClick={() => { setMode('register'); setError(''); }}>Daftar member</button></div><form className="auth-form" onSubmit={submit}>{mode === 'register' && <div className="field"><label>Nama lengkap</label><input required value={form.name} onChange={(event) => update('name', event.target.value)} /></div>}<div className="field"><label>Nickname / username</label><input required minLength="3" autoComplete="username" value={form.nickname} onChange={(event) => update('nickname', event.target.value)} /></div><div className="field"><label>Password</label><input required minLength="8" type="password" autoComplete={mode === 'login' ? 'current-password' : 'new-password'} value={form.password} onChange={(event) => update('password', event.target.value)} /></div>{mode === 'register' && <><div className="field"><label>Nomor HP / WhatsApp<input required type="tel" autoComplete="tel" placeholder="08xxxxxxxxxx" value={form.phone} onChange={(event) => update('phone', event.target.value)} /></label><small>Digunakan sesama peserta turnamen untuk menghubungi kamu.</small></div><div className="field"><label>Konfirmasi password</label><input required minLength="8" type="password" autoComplete="new-password" value={form.password_confirmation} onChange={(event) => update('password_confirmation', event.target.value)} /></div><div className="field"><label>Foto member (opsional)</label><input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => update('photo', event.target.files?.[0] || null)} /></div></>}{error && <div className="form-error">{error}</div>}<button className="button button-dark" disabled={busy}>{busy ? 'Memproses...' : mode === 'login' ? 'Masuk ke workspace' : 'Buat akun member'} <ArrowUpRight size={14} /></button></form>{mode === 'login' && <p className="auth-hint">Demo seed: <span className="mono">admin</span> atau <span className="mono">dimasprtm</span> - password <span className="mono">password</span></p>}</section></div>;
}

