    const generate = async () => { if (!initial?.id) return Swal.fire({ icon: 'info', title: 'Simpan tournament dulu', text: 'Bracket baru dapat dibuat setelah tournament tersimpan.' }); setBusy(true); try { const updated = await apiFetch('/api/tournaments/' + initial.id + '/randomize', { method: 'POST' }); setBracket(updated.bracket); onUpdated?.(updated); swalSuccess('Bracket berhasil dibuat.'); } catch (error) { swalError(error); } finally { setBusy(false); } };
