    const saveTournament = (result) => { replaceItem(result); if (result?.id && !items.some((item) => item.id === result.id)) setItems((current) => [result, ...current]); setEditor(null); swalSuccess('Turnamen tersimpan.'); };
    const remove = async (item) => { if (!(await swalConfirm('Hapus turnamen ' + item.name + '?'))) return; try { await apiFetch('/api/tournaments/' + item.id, { method: 'DELETE' }); setItems((current) => current.filter((value) => value.id !== item.id)); swalSuccess('Turnamen dihapus.'); } catch (error) { swalError(error); } };
