function useListPagination(items, fields, pageSize = 10) {
    const [query, setQuery] = useState('');
    const [page, setPage] = useState(1);
    const filtered = useMemo(() => {
        const needle = query.trim().toLowerCase();
        if (!needle) return items;
        return items.filter((item) => fields.some((field) => String(item?.[field] ?? '').toLowerCase().includes(needle)));
    }, [fields, items, query]);
    const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
    useEffect(() => { setPage(1); }, [query, pageSize]);
    useEffect(() => { if (page > totalPages) setPage(totalPages); }, [page, totalPages]);
    return { query, setQuery, page, setPage, filtered, totalPages, visible: filtered.slice((page - 1) * pageSize, page * pageSize) };
}
function ListToolbar({ label, query, setQuery, filteredCount, totalCount, pageSize, setPageSize }) {
    return <div className="list-toolbar"><div className="list-search"><Search size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Cari data..." aria-label={'Cari ' + label} /><kbd>/</kbd></div><div className="list-toolbar-meta"><span className="mono">{filteredCount} / {totalCount} {label}</span><select value={pageSize} onChange={(event) => setPageSize(Number(event.target.value))} aria-label="Jumlah data per halaman"><option value="10">10 / halaman</option><option value="20">20 / halaman</option><option value="40">40 / halaman</option></select></div></div>;
}
function ListPagination({ page, totalPages, setPage, always = false }) {
    if (totalPages <= 1 && !always) return null;
    const pages = Array.from({ length: totalPages }, (_, index) => index + 1);
    return <div className="list-pagination"><span className="mono">HALAMAN {String(page).padStart(2, '0')} / {String(totalPages).padStart(2, '0')}</span><div><button type="button" disabled={page === 1} onClick={() => setPage((current) => Math.max(1, current - 1))} aria-label="Halaman sebelumnya">←</button>{pages.map((number) => <button type="button" className={page === number ? 'active' : ''} key={number} onClick={() => setPage(number)}>{number}</button>)}<button type="button" disabled={page === totalPages} onClick={() => setPage((current) => Math.min(totalPages, current + 1))} aria-label="Halaman berikutnya">→</button></div></div>;
}
