function SponsorCrudPanel({ initial, onSaved }) {
    const [form, setForm] = useState({ name: initial?.name || '', link_url: initial?.link_url || '', sort_order: initial?.sort_order || 0, is_active: initial?.is_active ?? true, logo: null });
    const [busy, setBusy] = useState(false); const [error, setError] = useState('');
    const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
    const save = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { const body = new FormData(); body.append('name', form.name); body.append('link_url', form.link_url); body.append('sort_order', form.sort_order); body.append('is_active', form.is_active ? '1' : '0'); if (form.logo) body.append('logo', form.logo); const url = initial?.id ? '/api/sponsors/' + initial.id : '/api/sponsors'; if (initial?.id) body.append('_method', 'PUT'); onSaved(await apiFetch(url, { method: 'POST', body })); } catch (requestError) { setError(requestError.message); } finally { setBusy(false); } };
    return <form className="crud-form sponsor-crud-form" onSubmit={save}><div className="field"><label>Nama sponsor</label><input required value={form.name} onChange={(event) => update('name', event.target.value)} placeholder="Nama brand / sponsor" /></div><div className="field"><label>Link sponsor</label><input type="url" value={form.link_url} onChange={(event) => update('link_url', event.target.value)} placeholder="https://... (opsional)" /></div><div className="field"><label>Urutan tampil</label><input min="0" type="number" value={form.sort_order} onChange={(event) => update('sort_order', event.target.value)} /></div><div className="field"><label>Logo sponsor</label><input required={!initial?.id} type="file" accept="image/jpeg,image/png,image/webp,image/svg+xml" onChange={(event) => update('logo', event.target.files?.[0] || null)} /><span className="muted">PNG, JPG, WEBP, atau SVG · maksimal 10 MB</span></div><label className="check-field full"><input type="checkbox" checked={form.is_active} onChange={(event) => update('is_active', event.target.checked)} /> Tampilkan di Support By</label>{error && <div className="form-error full">{error}</div>}<div className="crud-actions full"><button className="button button-dark" disabled={busy}>{busy ? 'Menyimpan...' : 'Simpan sponsor'} <Check size={14} /></button></div></form>;
}
