function AccountListingCrudPanel({ initial, onSaved }) {
    const [form, setForm] = useState({ name: initial?.name || '', description: initial?.description || '', rank: initial?.rank || '', price: initial?.price || '', owner_nickname: initial?.owner_nickname || '', status: initial?.status || 'available', sort_order: initial?.sort_order || 0, is_active: initial?.is_active ?? true, images: [] });
    const [existingImages, setExistingImages] = useState(initial?.images || []);
    const [busy, setBusy] = useState(false); const [error, setError] = useState('');
    const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
    const save = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { const body = new FormData(); ['name', 'description', 'rank', 'price', 'owner_nickname', 'status', 'sort_order'].forEach((key) => body.append(key, form[key] ?? '')); body.append('is_active', form.is_active ? '1' : '0'); form.images.forEach((image) => body.append('images[]', image)); const url = initial?.id ? '/api/account-listings/' + initial.id : '/api/account-listings'; if (initial?.id) body.append('_method', 'PUT'); onSaved(await apiFetch(url, { method: 'POST', body })); } catch (requestError) { setError(requestError.message); } finally { setBusy(false); } };
    const removeImage = async (image) => { if (!(await swalConfirm('Hapus foto ini dari galeri?'))) return; try { await apiFetch('/api/account-listing-images/' + image.id, { method: 'DELETE' }); setExistingImages((current) => current.filter((value) => value.id !== image.id)); swalSuccess('Foto dihapus.'); } catch (requestError) { swalError(requestError); } };
    return <form className="crud-form account-listing-crud-form" onSubmit={save}><div className="field"><label>Nama akun</label><input required value={form.name} onChange={(event) => update('name', event.target.value)} placeholder="Nama listing akun" /></div><div className="field"><label>Rank / level</label><input value={form.rank} onChange={(event) => update('rank', event.target.value)} placeholder="Contoh: Elite Division" /></div><div className="field"><label>Harga</label><input min="0" type="number" value={form.price} onChange={(event) => update('price', event.target.value)} placeholder="Kosongkan untuk nego" /></div><div className="field"><label>Nickname pemilik</label><input value={form.owner_nickname} onChange={(event) => update('owner_nickname', event.target.value)} placeholder="@nickname" /></div><div className="field full"><label>Deskripsi akun</label><textarea rows="3" value={form.description} onChange={(event) => update('description', event.target.value)} placeholder="Detail akun yang boleh dilihat publik" /></div><div className="field"><label>Status listing</label><select value={form.status} onChange={(event) => update('status', event.target.value)}><option value="available">Tersedia</option><option value="sold">Terjual</option><option value="hidden">Disembunyikan</option></select></div><div className="field"><label>Urutan tampil</label><input min="0" type="number" value={form.sort_order} onChange={(event) => update('sort_order', event.target.value)} /></div><div className="field full"><label>Galeri foto akun</label><input multiple type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => update('images', Array.from(event.target.files || []))} /><span className="muted">Pilih beberapa foto sekaligus. Maksimal 20 foto, 10 MB per foto.</span><div className="account-upload-grid">{existingImages.map((image) => <div className="account-upload-item" key={image.id}><img src={image.image_url} alt="" /><button type="button" onClick={() => removeImage(image)} aria-label="Hapus foto"><X size={13} /></button></div>)}{form.images.map((image) => <div className="account-upload-item account-upload-new" key={image.name + image.lastModified}><span>{image.name}</span></div>)}</div></div><label className="check-field full"><input type="checkbox" checked={form.is_active} onChange={(event) => update('is_active', event.target.checked)} /> Tampilkan di halaman JB Akun</label>{error && <div className="form-error full">{error}</div>}<div className="crud-actions full"><button className="button button-dark" disabled={busy}>{busy ? 'Menyimpan...' : 'Simpan akun'} <Check size={14} /></button></div></form>;
}
function AccountListingsAdmin() {
    const [items, setItems] = useState([]); const [editor, setEditor] = useState(null); const [pageSize, setPageSize] = useState(10); const list = useListPagination(items, ['name', 'rank', 'owner_nickname', 'status'], pageSize); const load = () => apiFetch('/api/admin/accounts').then(setItems).catch(() => {});
    useEffect(() => { load(); }, []);
    const save = (result) => { setItems((current) => result?.id ? (current.some((item) => item.id === result.id) ? current.map((item) => item.id === result.id ? result : item) : [result, ...current]) : current); setEditor(null); swalSuccess('Listing akun tersimpan.'); };
    const remove = async (item) => { if (!(await swalConfirm('Hapus listing ' + item.name + '?'))) return; try { await apiFetch('/api/account-listings/' + item.id, { method: 'DELETE' }); setItems((current) => current.filter((value) => value.id !== item.id)); swalSuccess('Listing akun dihapus.'); } catch (error) { swalError(error); } };
    return <><div className="page-heading admin-page-heading"><div><div className="eyebrow">Admin / account desk</div><h2>Akun Total Football</h2><span className="page-subtitle">Kelola listing akun yang tampil di halaman publik.</span></div><button className="button button-dark" onClick={() => setEditor('new')}><Plus size={15} /> Tambah akun</button></div><section className="panel admin-list-panel\"><div className="admin-list-head"><span className="mono">ACCOUNT LISTINGS</span><strong>{items.length} akun</strong></div><ListToolbar label="AKUN" {...list} pageSize={pageSize} setPageSize={setPageSize} filteredCount={list.filtered.length} totalCount={items.length} /><div className="admin-list account-admin-list">{list.visible.map((item) => <div className="admin-list-row account-admin-row" key={item.id}><div className="account-admin-thumb">{item.image_url ? <img src={item.image_url} alt={item.name} /> : <span>{item.name.slice(0, 2).toUpperCase()}</span>}</div><div className="account-admin-copy"><strong>{item.name}</strong><span>{item.rank || 'Rank belum diisi'} · {item.price ? formatPrice(item.price) : 'Nego'}</span></div><span className={'status ' + (item.status === 'available' && item.is_active ? 'status-green' : 'status-orange')}>{item.status === 'available' && item.is_active ? 'Tampil' : item.status}</span><div className="row-actions"><button className="row-action" onClick={() => setEditor(item)} aria-label="Edit listing akun"><Pencil size={14} /></button><button className="row-action danger" onClick={() => remove(item)} aria-label="Hapus listing akun"><Trash2 size={14} /></button></div></div>)}{!list.visible.length && <div className="empty-roster"><strong>{list.filtered.length ? 'Tidak ada data di halaman ini.' : 'Belum ada listing akun.'}</strong></div>}</div><ListPagination page={list.page} totalPages={list.totalPages} setPage={list.setPage} /></section>{editor && <AdminModal title={editor === 'new' ? 'Tambah listing akun' : 'Edit listing akun'} onClose={() => setEditor(null)}><AccountListingCrudPanel key={editor === 'new' ? 'new' : editor.id} initial={editor === 'new' ? null : editor} onSaved={save} /></AdminModal>}</>;
}
